// Worker entry (wrangler.toml `main`). Puts the free Workers Cache API in front
// of the OpenNext worker so repeat page views never load the Next.js server.
// All logic lives in src/lib/edge-cache.ts; this file only wires the runtime.

// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- must pass both before and after a build
// @ts-ignore -- generated by `opennextjs-cloudflare build` (absent in a clean checkout)
import openNextWorker from './.open-next/worker.js';
import {
  cacheVersionFallback,
  createVersionSource,
  fetchDataVersion,
  handleWithEdgeCache,
  renderFailureTracker,
  type EdgeCacheStore,
} from './src/lib/edge-cache';
import { handleOgImage, type OgStore } from './src/lib/og-cache';
import { isMissingStaticAsset } from './src/lib/blocked-paths';
import { requestLogLine } from './src/lib/request-log';

// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- must pass both before and after a build
// @ts-ignore -- generated by `opennextjs-cloudflare build` (absent in a clean checkout)
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';

interface Env {
  NEXT_PUBLIC_SUPABASE_URL: string;
  NEXT_PUBLIC_SUPABASE_ANON_KEY: string;
  /** wrangler.toml [version_metadata]; changes on every deploy. */
  CF_VERSION_METADATA: { id: string };
  /** Free-tier KV for color social cards (#24). Optional: absent means no OG cache. */
  OG_CACHE?: OgStore;
}

interface ExecutionContext {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
}

let getVersion: (() => Promise<string | null>) | null = null;

async function respond(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  if (isMissingStaticAsset(new URL(request.url).pathname)) {
    return new Response('Not found', { status: 404, headers: { 'cache-control': 'no-store' } });
  }
  const cache = (caches as unknown as { default: EdgeCacheStore }).default;
  getVersion ??= createVersionSource(
    () => fetchDataVersion(env.NEXT_PUBLIC_SUPABASE_URL, env.NEXT_PUBLIC_SUPABASE_ANON_KEY),
    cacheVersionFallback(cache)
  );
  // OpenNext exposes this ctx to the app via getCloudflareContext(); queries.ts
  // flags failed reads on it so a degraded render is never cached.
  const tracker = renderFailureTracker(ctx);
  const origin = (req: Request) => openNextWorker.fetch(req, env, tracker.ctx);

  const edgeCached = (req: Request) =>
    handleWithEdgeCache(req, {
      cache,
      buildId: env.CF_VERSION_METADATA.id,
      getVersion: getVersion!,
      origin,
      waitUntil: (promise) => ctx.waitUntil(promise),
      renderFailed: tracker.failed,
    });

  // OG cards: global KV first; misses render through the per-colo page cache,
  // so 404s for unknown slugs are cached like any other page (#24).
  const og = await handleOgImage(request, {
    store: env.OG_CACHE,
    buildId: env.CF_VERSION_METADATA.id,
    getVersion,
    origin: edgeCached,
    waitUntil: (promise) => ctx.waitUntil(promise),
    renderFailed: tracker.failed,
  });
  return og ?? edgeCached(request);
}

const worker = {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const response = await respond(request, env, ctx);
    const colo = (request as Request & { cf?: { colo?: string } }).cf?.colo ?? null;
    console.log(requestLogLine(request, response, colo));
    return response;
  },
};

export default worker;
